<style>
.ce2-pearl-editorial{--pa-black:#211e1c;--pa-pearl:#f7f4ef;--pa-taupe:#a9a29b;background:var(--pa-pearl);color:var(--pa-black);font:400 19px/1.6 'Bodoni Moda',Georgia,serif}
.ce2-pearl-editorial h2{font:400 clamp(50px,7vw,110px)/.98 'Bodoni Moda',serif;letter-spacing:-.075em}
.ce2-pearl-editorial h3{font:400 clamp(30px,4vw,52px)/1.02 'Bodoni Moda',serif;letter-spacing:-.04em}
.ce2-pearl-editorial .pa-issue,.ce2-pearl-editorial .pa-nav,.ce2-pearl-editorial .pa-letter-caption,.ce2-pearl-editorial .pa-program-side{font:700 10px/1.6 'Manrope',sans-serif;letter-spacing:.19em;text-transform:uppercase}
.ce2-pearl-editorial .pa-hero{min-height:100svh;display:flex;flex-direction:column;align-items:center;padding:82px 22px 34px;background:#f6f3ed}
.ce2-pearl-editorial .pa-nav{position:absolute;top:0;left:0;right:0;z-index:10;display:flex;justify-content:space-between;gap:18px;align-items:center;padding:18px clamp(20px,4vw,75px)}
.ce2-pearl-editorial .pa-nav a{text-decoration:none;border:1px solid currentColor;padding:9px 11px}
.ce2-pearl-editorial .pa-hero-type{text-align:center;position:relative;z-index:3;margin:20px auto -22px}
.ce2-pearl-editorial .pa-hero-type>span{font:600 10px 'Manrope',sans-serif;letter-spacing:.3em}
.ce2-pearl-editorial .pa-hero h1{font:400 clamp(68px,13vw,178px)/.82 'Bodoni Moda',serif;display:flex;flex-direction:column;letter-spacing:-.085em;margin:30px 0 0;text-transform:uppercase}
.ce2-pearl-editorial .pa-hero h1 i{font:italic .45em 'Bodoni Moda',serif;line-height:1.2;letter-spacing:-.08em}
.ce2-pearl-editorial .pa-script{font:400 clamp(30px,4vw,55px) 'Allura',cursive;margin-top:12px}
.ce2-pearl-editorial .pa-hero-art{position:relative;width:min(670px,86%);margin:20px auto 0;display:flex;align-items:center;flex-direction:column}
.ce2-pearl-editorial .pa-hero-photo{width:100%;height:min(360px,42svh);filter:grayscale(1);box-shadow:0 8px 18px #0003}
.ce2-pearl-editorial .pa-pearl-thread{position:relative;width:90%;height:22px;margin-top:-13px;transform:rotate(-5deg);background:radial-gradient(circle,#fff 0 4px,#b5a9a0 4.5px 5px,transparent 5.5px) repeat-x;background-size:14px 20px;filter:drop-shadow(0 2px 2px #0005)}
.ce2-pearl-editorial .pa-hero-label{display:flex;justify-content:space-between;align-items:center;width:100%;font:700 10px 'Manrope',sans-serif;letter-spacing:.2em;margin-top:13px}
.ce2-pearl-editorial .pa-hero-footer{display:flex;align-items:center;justify-content:space-between;width:min(1150px,100%);gap:15px;margin:auto auto 0;font:700 10px 'Manrope',sans-serif;letter-spacing:.1em}
.ce2-pearl-editorial .pa-hero-footer a{text-decoration:none;border-bottom:1px solid;padding-bottom:7px}
.ce2-pearl-editorial .pa-letter{padding:100px clamp(20px,7vw,120px);background:#e7e1d9}
.ce2-pearl-editorial .pa-letter-head{display:flex;align-items:baseline;justify-content:space-between;gap:25px;margin:25px 0 60px;border-top:1px solid #605b56;padding-top:20px}
.ce2-pearl-editorial .pa-hand{font:400 42px 'Allura',cursive}
.ce2-pearl-editorial .pa-letter-grid{display:grid;grid-template-columns:1fr .9fr;align-items:start;gap:60px;max-width:1100px;margin:auto}
.ce2-pearl-editorial .pa-letter-grid>div{max-width:520px;font:400 clamp(24px,3vw,38px)/1.52 'Bodoni Moda',serif}
.ce2-pearl-editorial .pa-letter-caption{margin-top:35px;font-size:10px}
.ce2-pearl-editorial .pa-letter-photo{aspect-ratio:3/4;filter:grayscale(1)}
.ce2-pearl-editorial .pa-spread{display:grid;grid-template-columns:.88fr 1.12fr;background:#272524;color:#fcf8f0;min-height:730px}
.ce2-pearl-editorial .pa-spread-copy{padding:100px clamp(20px,5vw,70px);display:flex;flex-direction:column;justify-content:center}
.ce2-pearl-editorial .pa-spread-copy h2{margin:20px 0 55px}
.ce2-pearl-editorial .pa-spread-copy blockquote{font:italic clamp(36px,4vw,55px) 'Bodoni Moda',serif;margin-bottom:45px}
.ce2-pearl-editorial .pa-spread-copy>p{max-width:500px}
.ce2-pearl-editorial .pa-spread-number{display:block;margin-top:50px;font:700 12px 'Manrope',sans-serif;letter-spacing:.2em}
.ce2-pearl-editorial .pa-spread-images{position:relative;background:#b3aaa0;display:grid;grid-template-columns:1fr 1fr;gap:7px;padding:6px;align-items:center}
.ce2-pearl-editorial .pa-spread-shot{aspect-ratio:3/5;filter:grayscale(1)}
.ce2-pearl-editorial .pa-spread-shot-second{transform:translateY(50px)}
.ce2-pearl-editorial .pa-date{padding:135px clamp(20px,7vw,90px);background:#f6f4f0;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.ce2-pearl-editorial .pa-date-heading h2{margin:25px 0}.ce2-pearl-editorial .pa-date-heading h2 i{font-weight:400}
.ce2-pearl-editorial .pa-date-issue{border:1px solid #8f8980;background:#fff;max-width:530px;padding:50px 35px;display:flex;flex-direction:column;gap:8px;text-align:center;box-shadow:0 13px 35px #0001}
.ce2-pearl-editorial .pa-date-issue>span{font:600 10px 'Manrope',sans-serif;letter-spacing:.2em}
.ce2-pearl-editorial .pa-date-issue strong{font:400 clamp(28px,4vw,50px) 'Bodoni Moda',serif}
.ce2-pearl-editorial .pa-date-divider{height:1px;width:100%;background:#d6cfc9;margin:25px auto}
.ce2-pearl-editorial .pa-mini-calendar{max-width:330px;margin:30px auto 0;width:100%}
.ce2-pearl-editorial .ce2-calendar-grid .ce2-calendar-selected{background:#25211f;color:#25211f}
.ce2-pearl-editorial .pa-venue{padding:100px 24px;background:#d3ccc4}
.ce2-pearl-editorial .pa-venue-top{max-width:1100px;margin:auto}.ce2-pearl-editorial .pa-venue-top h2{margin:18px auto 50px}
.ce2-pearl-editorial .pa-venue-layout{display:grid;grid-template-columns:1.15fr 1fr;gap:60px;align-items:center;max-width:1100px;margin:auto}
.ce2-pearl-editorial .pa-venue-photo{aspect-ratio:4/5;filter:grayscale(1)}
.ce2-pearl-editorial .pa-venue-places{display:grid;gap:55px}
.ce2-pearl-editorial .pa-venue-places>div{border-bottom:1px solid #918a82;padding-bottom:35px}
.ce2-pearl-editorial .pa-venue-places span{font:700 11px 'Manrope',sans-serif;letter-spacing:.15em}
.ce2-pearl-editorial .pa-venue-places h3{margin:20px 0}
.ce2-pearl-editorial .pa-ceremony{padding:75px 20px;text-align:center;background:#f5f2ee}
.ce2-pearl-editorial .pa-ceremony h2{margin:20px}
.ce2-pearl-editorial .pa-program{display:grid;grid-template-columns:.85fr 1.15fr;background:#eeebe7}
.ce2-pearl-editorial .pa-program-photo{background:#272727;position:relative;padding:40px;display:grid;place-items:center}
.ce2-pearl-editorial .pa-program-image{width:85%;height:580px;filter:grayscale(1)}
.ce2-pearl-editorial .pa-program-side{position:absolute;right:20px;top:50%;color:#fff;writing-mode:vertical-rl;transform:translateY(-50%)}
.ce2-pearl-editorial .pa-program-copy{padding:100px clamp(25px,5vw,80px)}
.ce2-pearl-editorial .pa-program-copy h2{margin:22px 0 35px}
.ce2-pearl-editorial .pa-program-table>div{display:grid;grid-template-columns:120px 1fr;gap:12px;border-top:1px solid #9e958b;padding:22px 0}
.ce2-pearl-editorial .pa-program-table strong{font-size:28px;font-weight:500}.ce2-pearl-editorial .pa-program-table span{font-size:18px}
.ce2-pearl-editorial .pa-program-extra{white-space:pre-line;margin:20px 0}
.ce2-pearl-editorial .pa-people{padding:110px 25px;background:#252525;color:#f3eee7;text-align:center}
.ce2-pearl-editorial .pa-people h2{margin:18px auto 45px}
.ce2-pearl-editorial .pa-people-columns{max-width:850px;margin:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:25px}
.ce2-pearl-editorial .pa-people-columns>div{padding-top:25px;border-top:1px solid #afaaa5}
.ce2-pearl-editorial .pa-people-columns h3{font-size:30px;margin-bottom:15px}
.ce2-pearl-editorial .pa-people-columns p{white-space:pre-line}
.ce2-pearl-editorial .pa-gallery{padding:130px 24px;background:#f9f7f3;text-align:center}
.ce2-pearl-editorial .pa-gallery h2{margin:15px auto 75px}
.ce2-pearl-editorial .pa-gallery-grid{max-width:1100px;margin:auto;display:grid;grid-template-columns:1.25fr .8fr .8fr;grid-template-rows:240px 240px;gap:16px}
.ce2-pearl-editorial .pa-gallery-photo{filter:grayscale(1)}
.ce2-pearl-editorial .pa-gallery-first{grid-row:span 2}
.ce2-pearl-editorial .pa-gallery-second{grid-column:span 2}.ce2-pearl-editorial .pa-gallery-third,.ce2-pearl-editorial .pa-gallery-fourth{min-width:0}
.ce2-pearl-editorial .pa-gallery>p{font:italic 26px 'Bodoni Moda',serif;margin-top:60px}
.ce2-pearl-editorial .pa-attire{background:#c4b8ad;display:grid;grid-template-columns:1fr 1fr;padding:130px clamp(25px,6vw,100px);align-items:center;gap:45px}
.ce2-pearl-editorial .pa-attire h2{margin-top:20px}
.ce2-pearl-editorial .pa-attire-info{background:#f9f7f2;padding:50px 30px;text-align:center}
.ce2-pearl-editorial .pa-attire-info p{margin-bottom:12px}
.ce2-pearl-editorial .pa-attire-info h3{margin:30px auto 14px}
.ce2-pearl-editorial .pa-swatches{display:flex;justify-content:center;gap:11px;margin:26px auto 33px}
.ce2-pearl-editorial .pa-swatches i{width:36px;height:36px;border-radius:50%;background:#272424;box-shadow:inset 0 0 0 2px #ffffff60,0 2px 5px #0002}
.ce2-pearl-editorial .pa-swatches i:nth-child(2){background:#425a53}.ce2-pearl-editorial .pa-swatches i:nth-child(3){background:#6f695c}.ce2-pearl-editorial .pa-swatches i:nth-child(4){background:#bbb3a8}.ce2-pearl-editorial .pa-swatches i:nth-child(5){background:#eee8df}
.ce2-pearl-editorial .pa-rsvp{display:grid;grid-template-columns:1fr 1fr;background:#232222}
.ce2-pearl-editorial .pa-rsvp-black{color:#f9f6f1;padding:100px clamp(22px,6vw,90px);display:flex;justify-content:center;flex-direction:column}
.ce2-pearl-editorial .pa-rsvp-black>span{font:700 10px 'Manrope',sans-serif;letter-spacing:.18em}
.ce2-pearl-editorial .pa-rsvp-black h2{margin:30px 0}.ce2-pearl-editorial .pa-rsvp-white{background:#faf7f2;padding:80px clamp(22px,5vw,80px)}
.ce2-pearl-editorial .pa-rsvp-form button{background:#232222}
.ce2-pearl-editorial .pa-footer{padding:105px 25px;text-align:center;background:#f6f4f1}
.ce2-pearl-editorial .pa-footer>span{font:700 10px 'Manrope',sans-serif;letter-spacing:.2em}
.ce2-pearl-editorial .pa-footer h2{margin:22px 0}
.ce2-pearl-editorial .pa-footer a{font:700 10px 'Manrope',sans-serif;letter-spacing:.2em;display:inline-block;margin-top:35px}
.ce2-pearl-editorial .pa-intro{background:#1b1b1b}
.ce2-pearl-editorial .pa-curtain-trigger{position:relative;width:100%;height:100%;border:0;background:#111;overflow:hidden;display:grid;place-items:center}
.ce2-pearl-editorial .pa-intro-photo{position:absolute;inset:0;background-size:cover;background-position:center;filter:grayscale(1) brightness(.43)}
.ce2-pearl-editorial .pa-intro-copy{position:relative;z-index:2;color:#fff9f0;text-align:center;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:18px;padding:30px;max-width:95vw}
.ce2-pearl-editorial .pa-intro-copy small{font:700 11px 'Manrope',sans-serif;letter-spacing:.25em}
.ce2-pearl-editorial .pa-intro-copy strong{font:400 clamp(45px,9vw,116px)/1 'Bodoni Moda',serif}
.ce2-pearl-editorial .pa-intro-copy em{font:italic 29px 'Bodoni Moda',serif}
.ce2-pearl-editorial .pa-intro-copy>span{font:700 11px 'Manrope',sans-serif;letter-spacing:.19em;border:1px solid #fff8;padding:13px 19px}
.ce2-pearl-editorial .pa-curtain{position:absolute;top:0;bottom:0;width:50.3%;z-index:3;background:repeating-linear-gradient(90deg,#1e1b1a 0,#4b4040 7%,#211c1c 14%,#0f0e0e 20%);box-shadow:inset 0 0 60px #0009;transition:transform 1.8s cubic-bezier(.21,.77,.25,1)}
.ce2-pearl-editorial .pa-curtain-left{left:0}.ce2-pearl-editorial .pa-curtain-right{right:0}
.ce2-pearl-editorial .pa-intro-pearl{position:absolute;z-index:4;top:calc(50% - 35px);left:calc(50% - 35px);width:70px;height:70px;border-radius:50%;background:radial-gradient(circle at 36% 30%,#fff,#d8cec4 60%,#9d8c80);color:#fff;display:grid;place-items:center;box-shadow:0 4px 20px #0008;font-size:36px;transition:opacity .4s}
.ce2-pearl-editorial .pa-intro.is-opening .pa-curtain-left{transform:translateX(-100%)}
.ce2-pearl-editorial .pa-intro.is-opening .pa-curtain-right{transform:translateX(100%)}
.ce2-pearl-editorial .pa-intro.is-opening .pa-intro-pearl{opacity:0}
.ce2-pearl-editorial .ce2-animated{opacity:0;transform:translateY(12px);filter:blur(9px)}
.ce2-pearl-editorial .ce2-animated.ce2-in-view{opacity:1;transform:none;filter:blur(0)}
@media(max-width:800px){.ce2-pearl-editorial .pa-letter-grid,.ce2-pearl-editorial .pa-spread,.ce2-pearl-editorial .pa-date,.ce2-pearl-editorial .pa-venue-layout,.ce2-pearl-editorial .pa-program,.ce2-pearl-editorial .pa-attire,.ce2-pearl-editorial .pa-rsvp{grid-template-columns:1fr}.ce2-pearl-editorial .pa-spread-images{min-height:350px}.ce2-pearl-editorial .pa-program-photo{padding:30px}.ce2-pearl-editorial .pa-program-image{height:430px}.ce2-pearl-editorial .pa-people-columns{grid-template-columns:1fr}.ce2-pearl-editorial .pa-hero-footer{gap:8px}}
@media(max-width:550px){.ce2-pearl-editorial .pa-nav{font-size:9px;gap:5px;padding:17px 12px}.ce2-pearl-editorial .pa-nav span:nth-child(2){display:none}.ce2-pearl-editorial .pa-hero{min-height:680px}.ce2-pearl-editorial .pa-hero h1{font-size:clamp(55px,14vw,110px)}.ce2-pearl-editorial .pa-hero-art{width:94%}.ce2-pearl-editorial .pa-hero-photo{height:260px}.ce2-pearl-editorial .pa-hero-footer{font-size:8px}.ce2-pearl-editorial .pa-letter{padding:80px 20px}.ce2-pearl-editorial .pa-letter-head{display:block}.ce2-pearl-editorial .pa-gallery-grid{grid-template-rows:150px 150px;gap:8px}.ce2-pearl-editorial .pa-venue-layout{gap:25px}.ce2-pearl-editorial .pa-rsvp-black,.ce2-pearl-editorial .pa-rsvp-white{padding:70px 23px}}

/* Only the editorial introduction uses a theatrical flash. */
.ce2-pearl-editorial .pa-intro.pa-flash-frame::after{content:'';pointer-events:none;position:absolute;inset:0;z-index:6;background:#fff;animation:pa-camera-flash .9s ease-out both}
@keyframes pa-camera-flash{0%{opacity:.9}35%{opacity:.25}100%{opacity:0}}
</style>